// Extract status transitions from the Jira webhook changelog.
// A single webhook can carry multiple field changes; we emit one item per
// status change. No status change -> empty output, so nothing is posted.
const body = $input.first().json.body || $input.first().json;
const issue = body.issue || {};
const fields = issue.fields || {};
const changelog = body.changelog || {};
const items = changelog.items || [];
const ts = body.timestamp ? new Date(body.timestamp).toISOString() : new Date().toISOString();

const out = [];
for (const it of items) {
  if ((it.field || it.fieldId) === 'status') {
    out.push({
      json: {
        issueKey: issue.key || '',
        fromStatus: it.fromString || '',
        toStatus: it.toString || '',
        projectKey: (fields.project && fields.project.key) || '',
        issueType: (fields.issuetype && fields.issuetype.name) || '',
        assignee: (fields.assignee && fields.assignee.displayName) || '',
        changedAt: ts
      }
    });
  }
}
return out;
